+    const lost = task.inputs.files.filter(
+      (file) => !covered.has(file) && !file.endsWith("/CHANGELOG.md"),
+    );
+    assert.deepEqual(lost, [], `${id}: original files lost from raw or canonical Nx inputs`);
+  }
